mapper.select:
select 
from text_to_sql_eval_question


        and (
            question like concat('%', #{keyword}, '%')
            or final_answer like concat('%', #{keyword}, '%')
            or feedback_comment like concat('%', #{keyword}, '%')
            or remark like concat('%', #{keyword}, '%')
        )


        and business_id = #{businessId}


        and eval_target = #{evalTarget}


        and sample_category = #{sampleCategory}


        and source_type = #{sourceType}


        and feedback_result = #{feedbackResult}


        and status = #{status}


order by id desc
